def find_max_participants(n, k, preferences):
    from collections import defaultdict, deque

    def find_strongly_connected_components():
        index = 0
        stack = []
        indices = [-1] * n
        lowlink = [-1] * n
        on_stack = [False] * n
        sccs = []

        def strongconnect(v):
            nonlocal index
            indices[v] = index
            lowlink[v] = index
            index += 1
            stack.append(v)
            on_stack[v] = True

            for w in graph[v]:
                if indices[w] == -1:
                    strongconnect(w)
                    lowlink[v] = min(lowlink[v], lowlink[w])
                elif on_stack[w]:
                    lowlink[v] = min(lowlink[v], indices[w])

            if lowlink[v] == indices[v]:
                scc = []
                while True:
                    w = stack.pop()
                    on_stack[w] = False
                    scc.append(w)
                    if w == v:
                        break
                sccs.append(scc)

        for v in range(n):
            if indices[v] == -1:
                strongconnect(v)

        return sccs

    graph = defaultdict(list)
    for i in range(n):
        graph[i].append(preferences[i] - 1)

    sccs = find_strongly_connected_components()
    scc_map = {}
    for idx, scc in enumerate(sccs):
        for node in scc:
            scc_map[node] = idx

    condensed_graph = defaultdict(set)
    for v in range(n):
        for w in graph[v]:
            if scc_map[v] != scc_map[w]:
                condensed_graph[scc_map[v]].add(scc_map[w])

    in_degree = [0] * len(sccs)
    for u in condensed_graph:
        for v in condensed_graph[u]:
            in_degree[v] += 1

    zero_in_degree = deque([i for i in range(len(sccs)) if in_degree[i] == 0])
    visited = 0

    while zero_in_degree:
        u = zero_in_degree.popleft()
        visited += len(sccs[u])
        for v in condensed_graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                zero_in_degree.append(v)

    max_participants = min(n, visited + sum(1 for d in in_degree if d > 0))
    return max_participants

