    in_degree = [0] * (n + 1)

    for i in range(n):
        if preferences[i] != i + 1:
            graph[preferences[i]].append(i + 1)
            in_degree[i + 1] += 1

    # Kahn's algorithm for topological sorting
    queue = deque()
    for i in range(1, n + 1):
        if in_degree[i] == 0:
            queue.append(i)

    sorted_participants = []
    while queue:
        node = queue.popleft()
        sorted_participants.append(node)
        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # Find the maximum number of participants that can join
    # by selecting the longest path in the topological order
    max_joined = 0
    visited = [False] * (n + 1)

    def dfs(node):
        stack = [node]
        path_length = 0
        while stack:
            current = stack.pop()
            if not visited[current]:
                visited[current] = True
                path_length += 1
                for neighbor in graph[current]:
                    if not visited[neighbor]:
                        stack.append(neighbor)
        return path_length

    for participant in sorted_participants:
        if not visited[participant]:
            max_joined += dfs(participant)

    return min(max_joined, k)

