def max_participants(n, k, preferences):
    from collections import defaultdict, deque

    # Create a graph where each participant points to the one they depend on
    graph = defaultdict(list)
    in_degree = [0] * (n + 1)

    for i in range(n):
        if preferences[i] != i + 1:
            graph[preferences[i]].append(i + 1)
            in_degree[i + 1] += 1

    # Kahn's algorithm for topological sorting
    queue = deque()
    for i in range(1, n + 1):
        if in_degree[i] == 0:
            queue.append(i)

    sorted_participants = []
    while queue:
        node = queue.popleft()
        sorted_participants.append(node)
        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # If there's a cycle, the sorted list won't include all participants
    if len(sorted_participants) != n:
        return 0

    # Use a greedy approach to select the maximum number of participants
    selected = set()
    for participant in sorted_participants:
        if len(selected) < k:
            selected.add(participant)
            # Add the participant's dependencies to the selected set
            selected.update(graph[participant])

    return min(len(selected), k)

